#!/usr/bin/env python3
"""News-image entry: Tuesday 24 November 2026 — 55 stories, one 1024x1024 page.

Pure stdlib (struct/zlib/base64/hashlib). Text is drawn from grayscale glyph
bitmaps baked into FONTS (see /tmp/bake_fonts.py, DejaVu Sans / Sans Bold);
the PNG encoder is hand-rolled. Fully deterministic: no timestamps, no
randomness, no network. Run: python3 main.py  ->  entry.png next to main.py
"""
import base64
import hashlib
import os
import struct
import sys
import zlib

W = 1024
H = 1024

# ---------------------------------------------------------------- fonts
LINE_H = {"R10": 12, "R11": 13, "R12": 15, "R13": 16,
          "B12": 15, "B13": 16, "B16": 20, "B18": 23, "B26": 31}

GLYPHS = {}
for _name, _f in FONTS.items():
    _g = {}
    for _ch, (_adv, _xo, _yo, _w, _h, _b64) in _f["glyphs"].items():
        _g[_ch] = (_adv, _xo, _yo, _w, _h, base64.b64decode(_b64) if _b64 else b"")
    GLYPHS[_name] = {"ascent": _f["ascent"], "descent": _f["descent"], "g": _g}


def text_width(s, font):
    g = GLYPHS[font]["g"]
    w = 0
    for ch in s:
        gi = g.get(ch) or g["?"]
        w += gi[0]
    return w


def wrap(s, font, maxw):
    """Greedy word wrap -> list of lines (never empty)."""
    g = GLYPHS[font]["g"]
    lines, cur, curw = [], "", 0
    for word in s.split(" "):
        ww = text_width(word, font)
        add = ww if not cur else ww + text_width(" ", font)
        if cur and curw + add > maxw:
            lines.append(cur)
            cur, curw = word, ww
            while curw > maxw:  # hard-split a single overlong word
                cut, acc = 0, 0
                for ch in word:
                    cw = (g.get(ch) or g["?"])[0]
                    if acc + cw > maxw:
                        break
                    acc += cw
                    cut += 1
                lines.append(word[:cut])
                word = word[cut:]
                cur, curw = word, text_width(word, font)
        else:
            cur = word if not cur else cur + " " + word
            curw += add
    if cur:
        lines.append(cur)
    return lines or [""]


# ---------------------------------------------------------------- canvas
PAPER = (247, 243, 232)
INK = (20, 20, 20)
NAVY = (22, 40, 63)
RED = (176, 30, 36)
GREY = (90, 90, 90)
RULE = (160, 155, 140)
BOXBG = (238, 241, 245)


class Canvas:
    def __init__(self):
        self.px = bytearray(W * H * 3)
        row = bytes(PAPER) * W
        for y in range(H):
            self.px[y * W * 3:(y + 1) * W * 3] = row
        self._lut = {}

    def _blend_lut(self, fg, bg):
        key = (fg, bg)
        lut = self._lut.get(key)
        if lut is None:
            lut = []
            for a in range(256):
                lut.append((
                    (bg[0] * (255 - a) + fg[0] * a) // 255,
                    (bg[1] * (255 - a) + fg[1] * a) // 255,
                    (bg[2] * (255 - a) + fg[2] * a) // 255))
            self._lut[key] = lut
        return lut

    def rect(self, x, y, w, h, color):
        if w <= 0 or h <= 0:
            return
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(W, x + w)
        y1 = min(H, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(color) * (x1 - x0)
        for yy in range(y0, y1):
            o = (yy * W + x0) * 3
            self.px[o:o + len(row)] = row

    def hline(self, x, y, w, color, th=1):
        self.rect(x, y, w, th, color)

    def text(self, x, y_top, s, font, fg, bg):
        """Draw string with its ascender-top at y_top; returns width used."""
        lut = self._blend_lut(fg, bg)
        g = GLYPHS[font]["g"]
        pen = x
        for ch in s:
            gi = g.get(ch)
            if gi is None:
                gi = g["?"]
            adv, xo, yo, gw, gh, data = gi
            if gw and gh:
                for r in range(gh):
                    yy = y_top + yo + r
                    if yy < 0 or yy >= H:
                        continue
                    base = (yy * W + pen + xo) * 3
                    rowdata = data[r * gw:(r + 1) * gw]
                    for c in range(gw):
                        a = rowdata[c]
                        if a:
                            xx = pen + xo + c
                            if 0 <= xx < W:
                                o = base + c * 3
                                nr, ng, nb = lut[a]
                                self.px[o] = nr
                                self.px[o + 1] = ng
                                self.px[o + 2] = nb
            pen += adv
        return pen - x


def png_bytes(canvas):
    raw = bytearray()
    stride = W * 3
    for y in range(H):
        raw.append(0)
        raw += canvas.px[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(typ, data):
        out = struct.pack(">I", len(data)) + typ + data
        out += struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", comp) + chunk(b"IEND", b""))


