# ---------------------------------------------------------------- layout
# Configs tried in order; first that fits 1024px wins (deterministic).
# Also Today runs in 3 columns (14/13/13) so lines stay short at R11.
CONFIGS = [
    dict(name="C1", margin=20, hdr=50, med_font="R11", med_lh=13,
         also_lh=13, lead_body="R12", gap=8),
    dict(name="C2", margin=20, hdr=50, med_font="R10", med_lh=12,
         also_lh=12, lead_body="R12", gap=6),
    dict(name="C3", margin=18, hdr=44, med_font="R10", med_lh=12,
         also_lh=12, lead_body="R11", gap=3),
]
ALSO_COLS = 3
ALSO_ROWS = 14  # ceil(40/3); columns hold 14/13/13 items


def also_col_items():
    # Sequential reading order: col 1 = items 1-14, col 2 = 15-27,
    # col 3 = 28-40 (was round-robin: col k held items k, k+3, ...).
    cols = [[], [], []]
    sizes = [14, 13, 13]
    idx = 0
    for c, size in enumerate(sizes):
        for _ in range(size):
            if idx < len(ALSO):
                cols[c].append((idx + 1, ALSO[idx]))
                idx += 1
    return cols


def measure(cfg):
    m = cfg["margin"]
    cw = W - 2 * m
    lead_w = (cw - 2 * 16) // 3
    leads = []
    for tag, title, body in LEADS:
        tl = wrap(title, "B18", lead_w)
        bl = wrap(body, cfg["lead_body"], lead_w)
        leads.append((tag, tl, bl))
    lead_h = max(15 + 2 + len(tl) * 23 + 4 + len(bl) * LINE_H[cfg["lead_body"]]
                 for _, tl, bl in leads)
    med_w = (cw - 3 * 10) // 4
    meds = []
    for title, body in MEDIUMS:
        tl = wrap(title, "B12", med_w)
        bl = wrap(body, cfg["med_font"], med_w)
        meds.append((tl, bl))
    med_rows = []
    for r in range(3):
        row = meds[r * 4:(r + 1) * 4]
        med_rows.append(max(len(tl) * 15 + 3 + len(bl) * cfg["med_lh"] + 6
                            for tl, bl in row))
    also_w = (cw - 2 * 12) // 3
    cols = also_col_items()
    also_grid = []
    for c in range(ALSO_COLS):
        also_grid.append([wrap("%d. %s" % (n, t), "R11", also_w)
                          for n, t in cols[c]])
    also_rows = []
    for r in range(ALSO_ROWS):
        h = 0
        for c in range(ALSO_COLS):
            if r < len(also_grid[c]):
                h = max(h, len(also_grid[c][r]) * cfg["also_lh"] + 3)
        also_rows.append(h)
    mk_w = cw - 20
    mk_lines = [wrap(s, "R11", mk_w) for s in MARKETS]
    mk_foot = wrap(MARKETS_FOOT, "R11", mk_w)
    mk_h = (10 + 16 + 4 + sum(len(x) for x in mk_lines) * 13
            + 4 + len(mk_foot) * 13 + 10)
    gap = cfg["gap"]
    total = (cfg["hdr"] + 3 + 10 + lead_h + gap + 4 + 20
             + sum(med_rows) + 3 * 8 + gap + 4 + 20
             + sum(also_rows) + gap + mk_h + 4)
    return dict(leads=leads, lead_h=lead_h, meds=meds, med_rows=med_rows,
                also_grid=also_grid, also_rows=also_rows,
                mk_lines=mk_lines, mk_foot=mk_foot, mk_h=mk_h, total=total)


def section_label(cv, x, y, w, text):
    cv.text(x, y, text, "B13", NAVY, PAPER)
    cv.hline(x, y + 16, w, RULE, 1)
    return y + 20


def draw(cfg, ms):
    cv = Canvas()
    m = cfg["margin"]
    cw = W - 2 * m
    gap = cfg["gap"]
    # header band
    cv.rect(0, 0, W, cfg["hdr"], NAVY)
    cv.text(m, (cfg["hdr"] - 26) // 2 + 2, HEADER_DATE, "B26", (255, 255, 255), NAVY)
    bw = text_width(HEADER_COUNT, "B16") + 24
    bx = W - m - bw
    by = (cfg["hdr"] - 34) // 2
    cv.rect(bx, by, bw, 34, RED)
    cv.text(bx + 12, by + 7, HEADER_COUNT, "B16", (255, 255, 255), RED)
    cv.rect(0, cfg["hdr"], W, 3, RED)
    y = cfg["hdr"] + 3 + 10
    # leads: 3 columns
    lead_w = (cw - 2 * 16) // 3
    for i, (tag, tl, bl) in enumerate(ms["leads"]):
        x = m + i * (lead_w + 16)
        yy = y
        cv.text(x, yy, tag, "B12", RED, PAPER)
        yy += 15 + 2
        for ln in tl:
            cv.text(x, yy, ln, "B18", INK, PAPER)
            yy += 23
        yy += 4
        for ln in bl:
            cv.text(x, yy, ln, cfg["lead_body"], INK, PAPER)
            yy += LINE_H[cfg["lead_body"]]
        if i < 2:
            cv.rect(x + lead_w + 7, y, 1, ms["lead_h"], RULE)
    y += ms["lead_h"] + gap
    # mediums
    y = section_label(cv, m, y + 4, cw, "MORE TOP STORIES")
    med_w = (cw - 3 * 10) // 4
    for r in range(3):
        rh = ms["med_rows"][r]
        for c in range(4):
            tl, bl = ms["meds"][r * 4 + c]
            x = m + c * (med_w + 10)
            yy = y
            for ln in tl:
                cv.text(x, yy, ln, "B12", NAVY, PAPER)
                yy += 15
            yy += 3
            for ln in bl:
                cv.text(x, yy, ln, cfg["med_font"], INK, PAPER)
                yy += cfg["med_lh"]
        y += rh + 8
    y += gap
    # also today: 3 columns, sequential (1-14 / 15-27 / 28-40)
    y = section_label(cv, m, y + 4, cw, "ALSO TODAY \u2014 40 STORIES")
    also_w = (cw - 2 * 12) // 3
    for r in range(ALSO_ROWS):
        for c in range(ALSO_COLS):
            if r < len(ms["also_grid"][c]):
                lines = ms["also_grid"][c][r]
                x = m + c * (also_w + 12)
                yy = y
                for ln in lines:
                    cv.text(x, yy, ln, "R11", INK, PAPER)
                    yy += cfg["also_lh"]
        y += ms["also_rows"][r]
    y += gap
    # markets box (full-width strip lines)
    cv.rect(m, y, cw, ms["mk_h"], BOXBG)
    cv.rect(m, y, cw, 2, NAVY)
    cv.rect(m, y + ms["mk_h"] - 2, cw, 2, NAVY)
    cv.rect(m, y, 2, ms["mk_h"], NAVY)
    cv.rect(m + cw - 2, y, 2, ms["mk_h"], NAVY)
    yy = y + 10
    cv.text(m + 10, yy, "MARKETS", "B13", NAVY, BOXBG)
    yy += 16 + 4
    for lines in ms["mk_lines"]:
        for ln in lines:
            cv.text(m + 10, yy, ln, "R11", INK, BOXBG)
            yy += 13
    yy += 4
    for ln in ms["mk_foot"]:
        cv.text(m + 10, yy, ln, "R11", GREY, BOXBG)
        yy += 13
    return cv, y + ms["mk_h"] + 4


def main():
    assert len(LEADS) == 3 and len(MEDIUMS) == 12 and len(ALSO) == 40, \
        "story counts must be 3/12/40"
    chosen = None
    for cfg in CONFIGS:
        ms = measure(cfg)
        print("config %s: total=%d (lead=%d med=%s also=%d mk=%d)" % (
            cfg["name"], ms["total"], ms["lead_h"], ms["med_rows"],
            sum(ms["also_rows"]), ms["mk_h"]))
        if ms["total"] <= H:
            chosen = (cfg, ms)
            break
    if chosen is None:
        print("ERROR: no config fits in %d px" % H, file=sys.stderr)
        return 1
    cfg, ms = chosen
    cv, bottom = draw(cfg, ms)
    print("using %s, bottom=%d" % (cfg["name"], bottom))
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "entry.png")
    data = png_bytes(cv)
    with open(out, "wb") as f:
        f.write(data)
    print("wrote %s %d bytes sha256=%s" % (
        out, len(data), hashlib.sha256(data).hexdigest()))
    return 0


if __name__ == "__main__":
    sys.exit(main())
